import { mkdirSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";
import { accessHeaders } from "../npm-scripts/env.mjs";

const HOST = "stallion.kattebak.fyi";
const IP = process.argv[2];
const DIR = join(homedir(), "development", ".tmp", "stallion-expired");
mkdirSync(DIR, { recursive: true });
const id = () => Array.from(crypto.getRandomValues(new Uint8Array(16)), (b) => b.toString(36)).join("").slice(0, 25).padStart(25, "0");
const headers = accessHeaders();
const browser = await chromium.launch({ headless: true, args: [`--host-resolver-rules=MAP ${HOST} ${IP}`] });

const run = async (scheme, mode) => {
  const context = await browser.newContext({ ...devices["Galaxy Tab S9"], colorScheme: scheme });
  let auth = true;
  let broken = false;
  const errors = [];
  await context.route("**/*", (route) => {
    const req = route.request();
    const h = { ...req.headers() };
    if (auth && new URL(req.url()).host === HOST) Object.assign(h, headers);
    return route.continue({ headers: h });
  });
  const sockets = [];
  const handshakes = [];
  await context.routeWebSocket(/\/api\/.*ws/, (ws) => {
    if (broken && mode === "offline") {
      handshakes.push("refused-offline");
      ws.close();
      return;
    }
    handshakes.push(broken ? "unauth" : "auth");
    sockets.push(ws);
    ws.connectToServer();
  });
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push({ broken, text: m.text() }));
  page.on("pageerror", (e) => errors.push({ broken, text: `pageerror ${e.message}` }));
  const url = `https://${HOST}/b/${id()}`;
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
  await page.waitForTimeout(2000);
  broken = true;
  if (mode === "expired") {
    auth = false;
    await context.clearCookies();
  } else {
    await context.setOffline(true);
  }
  for (const ws of sockets) await ws.close().catch(() => {});
  const notice = page.locator(".notice");
  await notice.waitFor({ state: "visible", timeout: 20000 });
  await page.waitForTimeout(mode === "expired" ? 4000 : 1000);
  const text = (await notice.innerText()).replace(/\s+/g, " ").trim();
  const path = join(DIR, `${mode}-${scheme}.png`);
  await page.screenshot({ path });
  await context.close();
  return { mode, scheme, text, path, handshakes, errors };
};

for (const mode of ["expired", "offline"]) for (const scheme of ["light", "dark"]) console.log(JSON.stringify(await run(scheme, mode), null, 1));
await browser.close();
